{"content":"import math

def mean_stdev(xs):
    """Mean and population standard deviation of a list of numbers."""
    n = len(xs)
    if n == 0:
        raise ValueError("empty")
    mean = sum(xs) / n
    m = mean
    s = sum((d := x - m) * d for x in xs)
    var = s / n
    # guard against tiny negative due to rounding (shouldn't happen with two-pass, but be safe)
    if var <= 0.0:
        return (float(mean), 0.0 if var == 0.0 else 0.0)
    return (float(mean), math.sqrt(var))
