def mean_stdev(xs):
    n = len(xs)
    if n == 0:
        raise ValueError("empty")
    m = sum(xs) / n
    s = 0.0
    for x in xs:
        d = x - m
        s += d * d
    v = s / n
    if v <= 0.0:
        return (m, 0.0)
    return (m, _sqrt(v))
